import spidev
import time

def validate_channel(channel):
    if 0 <= channel <= 7:
        return True
    return False

def initialize_spi():
    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)
        spi.max_speed_hz = 1000000
        spi.mode = 0
        spi.lsbfirst = False
        return spi
    except Exception as e:
        print(f"SPI initialization failed: {e}")
        return None

def read_adc(spi, channel, normalized=False):
    if not validate_channel(channel):
        return -1

    try:
        adc_command = 0b00001100 | (channel & 0x07) << 2
        adc_response = spi.xfer2([adc_command, 0x00, 0x00])
        adc_count = ((adc_response[0] & 0x0F) << 8) | adc_response[1]

        if normalized:
            return adc_count / 4095.0
        else:
            return adc_count
    except Exception as e:
        print(f"ADC read failed: {e}")
        return -1

def main():
    spi = initialize_spi()
    if spi is None:
        print("Failed to initialize SPI.")
        return

    try:
        raw_value = read_adc(spi, 0)
        normalized_value = read_adc(spi, 0, normalized=True)

        if raw_value == -1:
            print("Failed to read raw ADC value.")
        else:
            print(f"Raw ADC value: {raw_value}")

        if normalized_value == -1:
            print("Failed to read normalized ADC value.")
        else:
            print(f"Normalized ADC value: {normalized_value:.4f}")

    finally:
        spi.close()

if __name__ == "__main__":
    main()

