import spidev
import sys

def read_mcp3208(channel):
    if not (0 <= channel <= 7):
        raise ValueError("Channel must be between 0 and 7.")

    # Open SPI device
    try:
        spi = spidev.SpiDev()
        spi.open(0, 0)  # Open SPI0/CE0
        spi.max_speed_hz = 1000000  # Set SPI clock to 1 MHz
        spi.mode = 0  # Set SPI mode 0
    except Exception as e:
        print(f"Error opening SPI device: {e}")
        sys.exit(1)

    try:
        # Construct the command to read from the MCP3208
        # Start bit (1), single-ended mode (1), channel selection (3 bits)
        command = 0b00001100 | (channel & 0b00000111)
        adc = spi.xfer2([command, 0x00, 0x00])

        # Combine the two bytes into a 12-bit result
        result = ((adc[0] & 0x0F) << 8) | adc[1]
        print(f"Raw ADC value from channel {channel}: {result}")
    except Exception as e:
        print(f"Error during SPI transfer: {e}")
    finally:
        spi.close()

if __name__ == "__main__":
    try:
        read_mcp3208(3)
    except ValueError as ve:
        print(f"ValueError: {ve}")
    except Exception as e:
        print(f"Unexpected error: {e}")

import spidev
import RPi.GPIO as GPIO
import time
import logging

class SmartGardenController:
    def __init__(self):
        self.spi = spidev.SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = 1350000
        self.pump_relay_pin = 18
        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pump_relay_pin, GPIO.OUT)
            GPIO.output(self.pump_relay_pin, GPIO.LOW)
        except Exception as e:
            logging.error(f"Failed to set up GPIO: {e}")
            self.close()
            raise

    def read_moisture(self):
        try:
            adc = self.spi.xfer2([1, (8 + 0) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"Failed to read from SPI: {e}")
            return None

    def run_pump(self, seconds):
        try:
            GPIO.output(self.pump_relay_pin, GPIO.HIGH)
            time.sleep(seconds)
        finally:
            GPIO.output(self.pump_relay_pin, GPIO.LOW)

    def irrigation_cycle(self):
        moisture = self.read_moisture()
        if moisture is not None and moisture < 450:
            self.run_pump(2)
            return True
        return False

    def close(self):
        try:
            self.spi.close()
        except Exception as e:
            logging.error(f"Failed to close SPI: {e}")
        finally:
            GPIO.cleanup()

def schedule_cycles(controller, cycle_count, interval_seconds):
    for _ in range(cycle_count):
        if controller.irrigation_cycle():
            logging.info("Irrigation cycle executed.")
        else:
            logging.info("No irrigation needed.")
        time.sleep(interval_seconds)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    controller = None
    try:
        controller = SmartGardenController()
        schedule_cycles(controller, 10, 3)
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        if controller:
            controller.close()

