import time
import threading
import queue
import logging
import argparse
from gpiozero import DigitalInputDevice
import spidev
import RPi.GPIO as GPIO

class SoundSensor:
    def __init__(self, sensor_id, sensor_type, threshold, sample_rate, gpio_pins, channels, spi_speed=1000000, log_queue=None):
        self.sensor_id = sensor_id
        self.sensor_type = sensor_type
        self.threshold = threshold
        self.sample_rate = sample_rate
        self.gpio_pins = gpio_pins
        self.channels = channels
        self.spi_speed = spi_speed
        self.log_queue = log_queue
        self.spi = None
        self.stop_event = threading.Event()

        if self.sensor_type == 'digital':
            self.setup_digital_sensor()
        elif self.sensor_type == 'analog':
            self.setup_analog_sensor()
        else:
            raise ValueError("Invalid sensor type. Must be 'digital' or 'analog'.")

    def setup_digital_sensor(self):
        try:
            GPIO.setmode(GPIO.BCM)
            self.digital_sensors = [DigitalInputDevice(pin, pull_up=True) for pin in self.gpio_pins]
        except Exception as e:
            logging.error(f"Error setting up digital sensors: {e}")
            raise

    def setup_analog_sensor(self):
        try:
            self.spi = spidev.SpiDev()
            self.spi.open(0, 0)
            self.spi.max_speed_hz = self.spi_speed
        except Exception as e:
            logging.error(f"Error setting up analog sensor: {e}")
            raise

    def read_analog(self, channel):
        try:
            adc = self.spi.xfer2([1, (8 + channel) << 4, 0])
            data = ((adc[1] & 3) << 8) + adc[2]
            return data
        except Exception as e:
            logging.error(f"Error reading analog channel {channel}: {e}")
            return None

    def run(self):
        try:
            while not self.stop_event.is_set():
                if self.sensor_type == 'digital':
                    for sensor in self.digital_sensors:
                        if sensor.value:
                            self.log_event(f"Digital sensor {sensor.pin} triggered")
                elif self.sensor_type == 'analog':
                    for channel in self.channels:
                        value = self.read_analog(channel)
                        if value is not None and value >= self.threshold:
                            self.log_event(f"Analog sensor on channel {channel} exceeded threshold with value {value}")

                time.sleep(1 / self.sample_rate)
        except Exception as e:
            logging.error(f"Error in run method: {e}")

    def log_event(self, message):
        if self.log_queue:
            try:
                self.log_queue.put(f"Sensor {self.sensor_id}: {message}")
            except Exception as e:
                logging.error(f"Error logging event: {e}")

    def stop(self):
        self.stop_event.set()
        if self.sensor_type == 'digital':
            GPIO.cleanup(self.gpio_pins)
        if self.sensor_type == 'analog' and self.spi:
            self.spi.close()

def main():
    parser = argparse.ArgumentParser(description="Sound Sensor Monitoring")
    parser.add_argument('--sensor_type', required=True, choices=['digital', 'analog'], help="Type of sensor")
    parser.add_argument('--threshold', type=int, required=True, help="Threshold value for analog sensor")
    parser.add_argument('--sample_rate', type=float, required=True, help="Sample rate in Hz")
    parser.add_argument('--log_file', required=True, help="Log file path")
    parser.add_argument('--gpio_pins', type=int, nargs='*', help="GPIO pins for digital sensors")
    parser.add_argument('--channels', type=int, nargs='*', help="ADC channels for analog sensors")
    parser.add_argument('--spi_speed', type=int, default=1000000, help="SPI speed")
    parser.add_argument('--sensor_ids', required=True, nargs='+', help="Sensor IDs")

    args = parser.parse_args()

    logging.basicConfig(filename=args.log_file, level=logging.ERROR)
    log_queue = queue.Queue()

    sensors = []
    for sensor_id in args.sensor_ids:
        try:
            sensor = SoundSensor(
                sensor_id=sensor_id,
                sensor_type=args.sensor_type,
                threshold=args.threshold,
                sample_rate=args.sample_rate,
                gpio_pins=args.gpio_pins,
                channels=args.channels,
                spi_speed=args.spi_speed,
                log_queue=log_queue
            )
            sensors.append(sensor)
        except Exception as e:
            logging.error(f"Error creating sensor {sensor_id}: {e}")

    threads = []
    for sensor in sensors:
        thread = threading.Thread(target=sensor.run)
        thread.start()
        threads.append(thread)

    try:
        while True:
            time.sleep(1)
    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        for sensor in sensors:
            sensor.stop()
        for thread in threads:
            thread.join()

if __name__ == "__main__":
    main()

