        self.pga_map = {6144: 1, 4096: 2, 2048: 4, 1024: 8, 512: 16, 256: 32}

    def read(self, channel, pga):
        if channel not in self.channel_map:
            raise ValueError("Invalid channel. Must be 0, 1, 2, or 3.")
        if pga not in self.pga_map:
            raise ValueError("Invalid PGA value. Must be 6144, 4096, 2048, 1024, 512, or 256.")

        try:
            self.ads.gain = self.pga_map[pga]
            analog_in = AnalogIn(self.ads, self.channel_map[channel])
            time.sleep(0.01)  # Wait for conversion to complete
            raw_value = analog_in.value
            voltage = (raw_value * 3.3 * pga) / 32768  # Scale to millivolts
            return voltage
        except Exception as e:
            raise RuntimeError(f"Error reading from ADC: {str(e)}")

    def __del__(self):
        try:
            self.i2c.deinit()
        except Exception:
            pass  # Ignore errors during cleanup

# Example usage:
if __name__ == "__main__":
    adc = ADS1x15ADC()
    try:
        voltage = adc.read(channel=0, pga=2048)
        print(f"Voltage: {voltage:.2f} mV")
    except Exception as e:
        print(f"Error: {str(e)}")
    finally:
        del adc
