import time
import signal
import logging
from gpiozero import DistanceSensor, Servo
from gpiozero.pins.pigpio import PiGPIOFactory
from picamera2 import Picamera2
from adafruit_pid import PID
import paho.mqtt.client as mqtt

# Configure logging
logging.basicConfig(level=logging.INFO)
logger = logging.getLogger(__name__)

class BalanceBeamController:
    def __init__(self):
        self.factory = PiGPIOFactory()
        self.sensor = DistanceSensor(echo=24, trigger=23, max_distance=1, pin_factory=self.factory)
        self.servo = Servo(25, pin_factory=self.factory)
        self.pid = PID(1.0, 0.1, 0.05, setpoint=25)
        self.pid.output_limits = (-50, 50)
        self.in_tolerance_count = 0
        self.running = True

        # MQTT setup
        self.client = mqtt.Client(mqtt.CallbackAPIVersion.VERSION2)
        self.client.on_connect = self.on_connect
        self.client.on_message = self.on_message
        self.client.connect("localhost", 1883, 60)
        self.client.loop_start()

    def on_connect(self, client, userdata, flags, rc):
        logger.info("Connected to MQTT broker with result code " + str(rc))
        client.subscribe("balance_beam/control")

    def on_message(self, client, userdata, msg):
        logger.info(f"Received message: {msg.payload.decode()}")

    def read_sensor(self):
        try:
            distance = self.sensor.distance * 100  # Convert to centimeters
            logger.info(f"Sensor reading: {distance:.2f} cm")
            return distance
        except Exception as e:
            logger.error(f"Sensor read error: {e}")
            return None

    def move_servo(self, angle):
        try:
            self.servo.value = angle / 50.0  # Convert to -1 to 1 range
            logger.info(f"Servo command: {angle:.2f} degrees")
        except Exception as e:
            logger.error(f"Servo command error: {e}")

    def control_loop(self):
        while self.running:
            distance = self.read_sensor()
            if distance is not None:
                error = distance - self.pid.setpoint
                logger.info(f"Computed error: {error:.2f} cm")

                if abs(error) <= 25:
                    self.pid.setpoint = distance
                    output = self.pid(distance)
                    self.move_servo(output)

                    if abs(error) <= 3:
                        self.in_tolerance_count += 1
                        if self.in_tolerance_count >= 3:
                            self.servo.detach()
                            logger.info("Servo detached due to consecutive in-tolerance readings")
                    else:
                        self.in_tolerance_count = 0
                else:
                    logger.warning(f"Error exceeds maximum tolerance: {abs(error):.2f} cm")
            else:
                logger.warning("Skipping PID update due to sensor read failure")

            time.sleep(0.1)

    def cleanup(self):
        self.running = False
        try:
            self.servo.detach()
        except Exception as e:
            logger.error(f"Error detaching servo: {e}")

        try:
            self.sensor.close()
        except Exception as e:
            logger.error(f"Error closing sensor: {e}")

        try:
            self.client.loop_stop()
            self.client.disconnect()
        except Exception as e:
            logger.error(f"Error disconnecting MQTT client: {e}")

def main():
    controller = BalanceBeamController()
    try:
        controller.control_loop()
    except KeyboardInterrupt:
        logger.info("Received SIGINT, stopping control loop")
    finally:
        controller.cleanup()

if __name__ == "__main__":
    main()

