import serial
import paho.mqtt.client as mqtt
from gpiozero import LED
from picamera2 import Picamera2
from fractions import Fraction
from typing import Tuple, Union
import sys

# Constants
UART_PORT = "/dev/serial0"
BAUD_RATE = 9600
MQTT_BROKER = "localhost"
MQTT_PORT = 1883
MQTT_TOPIC = "gps/data"

# Initialize hardware
led = LED(17)  # Assuming LED is connected to GPIO 17
picam2 = Picamera2()
picam2.start()

def degrees_decimal_to_dms(degrees_decimal: float) -> Tuple[int, int, float]:
    if not isinstance(degrees_decimal, (int, float)):
        raise ValueError("degrees_decimal must be a real number")

    sign = -1 if degrees_decimal < 0 else 1
    degrees_decimal = abs(degrees_decimal)
    degrees = int(degrees_decimal)
    minutes_float = (degrees_decimal - degrees) * 60
    minutes = int(minutes_float)
    seconds = (minutes_float - minutes) * 60

    return (sign * degrees, sign * minutes, sign * seconds)

def number_to_exif_rational(number: Union[int, float]) -> Tuple[int, int]:
    if not isinstance(number, (int, float)):
        raise ValueError("number must be a real number")

    try:
        frac = Fraction(number).limit_denominator(1000)
    except (ValueError, OverflowError):
        raise ValueError("number cannot be converted to a fraction")

    if not isinstance(frac.numerator, int) or not isinstance(frac.denominator, int):
        raise TypeError("numerator and denominator must be integers")

    return (frac.numerator, frac.denominator)

def setup_serial():
    try:
        return serial.Serial(UART_PORT, BAUD_RATE, timeout=1)
    except serial.SerialException as e:
        print(f"Error setting up serial: {e}")
        sys.exit(1)

def setup_mqtt():
    client = mqtt.Client()
    try:
        client.connect(MQTT_BROKER, MQTT_PORT, 60)
        return client
    except Exception as e:
        print(f"Error connecting to MQTT broker: {e}")
        sys.exit(1)

def read_gps_data(ser):
    while True:
        try:
            data = ser.readline().decode('ascii', errors='replace').strip()
            if data.startswith('$GPGGA'):
                return parse_gpgga(data)
        except serial.SerialException as e:
            print(f"Error reading GPS data: {e}")
            return None

def parse_gpgga(data):
    fields = data.split(',')
    if len(fields) < 15:
        return None

    try:
        lat = float(fields[2])
        lat_dir = fields[3]
        lon = float(fields[4])
        lon_dir = fields[5]

        if lat_dir == 'S':
            lat = -lat
        if lon_dir == 'W':
            lon = -lon

        return {
            'latitude': degrees_decimal_to_dms(lat),
            'longitude': degrees_decimal_to_dms(lon),
            'altitude': number_to_exif_rational(float(fields[9])),
            'timestamp': fields[1]
        }
    except (ValueError, IndexError):
        return None

def main():
    ser = setup_serial()
    mqtt_client = setup_mqtt()

    try:
        while True:
            gps_data = read_gps_data(ser)
            if gps_data:
                led.on()
                mqtt_client.publish(MQTT_TOPIC, str(gps_data))
                led.off()
    except KeyboardInterrupt:
        print("Program terminated by user")
    finally:
        ser.close()
        mqtt_client.disconnect()
        picam2.stop()
        led.close()

if __name__ == "__main__":
    main()

