import signal
import sys
import time
import logging
from gpiozero import PWMOutputDevice
from contextlib import contextmanager

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
TEMP_FILE = '/sys/class/thermal/thermal_zone0/temp'
PWM_PIN = 17
DEFAULT_PWM = 1.0
FAN_SPEED_THRESHOLDS = [45, 50, 55, 65]
PWM_VALUES = [0.4, 0.6, 0.8, 1.0]
POLL_INTERVAL = 5

# Validate PWM values
if len(FAN_SPEED_THRESHOLDS) != len(PWM_VALUES):
    raise ValueError("Thresholds and PWM values arrays must be of equal length.")
if any(not (0.0 <= pwm <= 1.0) for pwm in PWM_VALUES):
    raise ValueError("PWM values must be in the range 0.0 to 1.0.")

@contextmanager
def managed_pwm(pin):
    pwm_device = None
    try:
        pwm_device = PWMOutputDevice(pin)
        pwm_device.value = DEFAULT_PWM
        logging.info("Fan started at full speed.")
        yield pwm_device
    except Exception as e:
        logging.error(f"Failed to initialize PWM on pin {pin}: {e}")
        sys.exit(1)
    finally:
        if pwm_device:
            try:
                pwm_device.close()
            except Exception as e:
                logging.error(f"Error closing PWM device: {e}")

def get_cpu_temperature():
    try:
        with open(TEMP_FILE, 'r') as f:
            temp_milli = int(f.read().strip())
        return temp_milli / 1000.0
    except Exception as e:
        logging.error(f"Error reading temperature: {e}")
        return None

def map_temperature_to_pwm(temp):
    for threshold, pwm in zip(FAN_SPEED_THRESHOLDS, PWM_VALUES):
        if temp > threshold:
            return pwm
    return PWM_VALUES[0]

def signal_handler(signum, frame):
    logging.info("Received signal to terminate. Shutting down fan.")
    sys.exit(0)

def main():
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with managed_pwm(PWM_PIN) as pwm_device:
        while True:
            temp = get_cpu_temperature()
            if temp is not None:
                target_pwm = map_temperature_to_pwm(temp)
                try:
                    pwm_device.value = target_pwm
                    logging.info(f"Temperature: {temp:.1f}°C, Target PWM: {target_pwm:.1f}")
                except Exception as e:
                    logging.error(f"Error setting PWM duty cycle: {e}")
            time.sleep(POLL_INTERVAL)

if __name__ == "__main__":
    main()

