import time
from spidev import SpiDev
from gpiozero import LED

class MAX7219:
    def __init__(self, cs_pin, spi_speed=1000000):
        self.cs = LED(cs_pin)
        self.cs.off()
        self.spi = SpiDev()
        self.spi.open(0, 0)
        self.spi.max_speed_hz = spi_speed
        self.spi.mode = 0b00
        self.init_display()

    def init_display(self):
        self._write(0x0C, 0x01)  # Turn on chip
        self._write(0x09, 0x00)  # Decode mode
        self._write(0x0A, 0x0F)  # Intensity
        self._write(0x0B, 0x07)  # Scan limit
        self._write(0x0F, 0x00)  # Display test off

    def _write(self, address, data):
        self.cs.on()
        try:
            self.spi.xfer2([address, data])
        finally:
            self.cs.off()

    def display_char(self, char_map, char):
        if char in char_map:
            for i in range(8):
                self._write(i + 1, char_map[char][i])
        else:
            print(f"Character '{char}' not found in char_map.")

    def clear(self):
        for i in range(1, 9):
            self._write(i, 0x00)

    def close(self):
        self.clear()
        self._write(0x0C, 0x00)  # Turn off chip
        self.spi.close()

def main():
    char_map = {
        'H': [0x3E, 0x51, 0x49, 0x45, 0x45, 0x49, 0x51, 0x3E]
    }

    try:
        display = MAX7219(cs_pin=8)
        display.display_char(char_map, 'H')
        time.sleep(5)
    except (IOError, OSError) as e:
        print(f"Error during SPI communication: {e}")
    finally:
        if 'display' in locals():
            display.close()

if __name__ == "__main__":
    main()

