import sys

# Constants
I2C_ADDRESS = 0x20  # Default address for PCF8574
I2C_BUS = 1  # Default I2C bus on Raspberry Pi
SLEEP_INTERVAL = 0.1  # 100 ms
RETRY_DELAY = 1  # 1 second

# Initialize I2C bus
try:
    bus = smbus.SMBus(I2C_BUS)
except IOError:
    print("Error: Unable to access I2C bus.")
    sys.exit(1)

def read_pcf8574():
    try:
        return bus.read_byte(I2C_ADDRESS)
    except IOError:
        print("Error: Unable to read from PCF8574.")
        return None

def cleanup(signum, frame):
    print("\nCleaning up...")
    bus.close()
    sys.exit(0)

# Register the cleanup function to handle Ctrl+C
signal.signal(signal.SIGINT, cleanup)

def main():
    while True:
        data = read_pcf8574()
        if data is not None:
            for i in range(8):
                if not (data & (1 << i)):  # Active-low logic
                    print(f"Obstacle detected by sensor {i}")
        else:
            print("Error: No data received from PCF8574. Retrying...")
            time.sleep(RETRY_DELAY)
        time.sleep(SLEEP_INTERVAL)

if __name__ == "__main__":
