import smbus2
import time
import signal
import logging

class DHT20:
    def __init__(self, bus_number=1, address=0x38):
        self.bus = None
        self.address = address
        try:
            self.bus = smbus2.SMBus(bus_number)
            self._verify_sensor()
        except Exception as e:
            logging.error(f"Failed to initialize DHT20: {e}")
            self.bus = None

    def _verify_sensor(self):
        try:
            status = self.bus.read_byte_data(self.address, 0x71)
            if status != 0x18:
                raise ValueError("Sensor verification failed")
        except Exception as e:
            logging.error(f"Sensor verification error: {e}")
            raise

    def measure(self):
        if self.bus is None:
            return None, None, True

        try:
            self.bus.write_byte(self.address, 0xAC)
            start_time = time.time()
            while time.time() - start_time < 0.1:
                status = self.bus.read_byte_data(self.address, 0x71)
                if status & 0x08:
                    break
                time.sleep(0.01)
            else:
                logging.error("Timeout waiting for data ready")
                return None, None, True

            data = self.bus.read_i2c_block_data(self.address, 0x71, 7)
            raw_humidity = (data[1] << 12) | (data[2] << 4) | (data[3] >> 4)
            raw_temperature = ((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]

            crc = self._crc8(data[:6])
            if crc != data[6]:
                logging.error("CRC check failed")
                return None, None, True

            temperature = -45 + 175 * (raw_temperature / (2**20))
            humidity = 100 * (raw_humidity / (2**20))

            return temperature, humidity, False
        except Exception as e:
            logging.error(f"Measurement error: {e}")
            return None, None, True

    def _crc8(self, data):
        polynomial = 0x31
        crc = 0xFF
        for byte in data:
            crc ^= byte
            for _ in range(8):
                if crc & 0x80:
                    crc = (crc << 1) ^ polynomial
                else:
                    crc <<= 1
                crc &= 0xFF
        return crc

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None

def signal_handler(signum, frame):
    global dht20
    if dht20:
        dht20.close()
    exit(0)

if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    dht20 = DHT20()
    temperature, humidity, crc_error = dht20.measure()
    if crc_error:
        print("Measurement failed due to CRC error")
    else:
        print(f"Temperature: {temperature:.2f}°C")
        print(f"Humidity: {humidity:.2f}%")

    dht20.close()

