import argparse
import json
import logging
import socket
import sys
from gpiozero import OutputDevice
from gpiozero.exc import GPIOZeroError

def setup_logging(log_file_path):
    logging.basicConfig(filename=log_file_path, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')

def parse_arguments():
    parser = argparse.ArgumentParser(description='Hydroponics Controller')
    parser.add_argument('--relay_pin', type=int, default=17, help='GPIO pin for the relay')
    parser.add_argument('--dht_pin', type=int, default=4, help='GPIO pin for the DHT11 sensor')
    parser.add_argument('--port', type=int, default=12345, help='Port to listen on')
    parser.add_argument('--allowed_ip', type=str, default='192.168.1.100', help='Allowed IP address')
    parser.add_argument('--log_file', type=str, default='hydroponics.log', help='Path to the log file')
    return parser.parse_args()

def setup_gpio(relay_pin):
    try:
        pump = OutputDevice(relay_pin)
        pump.off()
        return pump
    except GPIOZeroError as e:
        logging.error(f"Failed to setup GPIO: {e}")
        sys.exit(1)

def handle_client_connection(client_socket, pump, allowed_ip):
    client_address = client_socket.getpeername()
    if client_address[0] != allowed_ip:
        logging.warning(f"Unauthorized connection attempt from {client_address}")
        client_socket.close()
        return

    try:
        data = client_socket.recv(1024).decode('utf-8')
        command = json.loads(data)
        if command['command'] == 'pump_on':
            pump.on()
            response = {"status": "on", "temperature": 25.0}
        elif command['command'] == 'pump_off':
            pump.off()
            response = {"status": "off", "temperature": 25.0}
        elif command['command'] == 'get_status':
            status = "on" if pump.value else "off"
            response = {"status": status, "temperature": 25.0}
        else:
            response = {"error": "Invalid command"}
        client_socket.sendall(json.dumps(response).encode('utf-8'))
    except json.JSONDecodeError:
        logging.error("Malformed JSON received")
        client_socket.sendall(json.dumps({"error": "Malformed JSON"}).encode('utf-8'))
    except Exception as e:
        logging.error(f"Error handling client: {e}")
    finally:
        client_socket.close()

def main():
    args = parse_arguments()
    setup_logging(args.log_file)

    pump = setup_gpio(args.relay_pin)

    try:
        server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        server_socket.bind(('0.0.0.0', args.port))
        server_socket.listen(1)
        logging.info(f"Listening on port {args.port}")

        while True:
            client_socket, _ = server_socket.accept()
            handle_client_connection(client_socket, pump, args.allowed_ip)
    except KeyboardInterrupt:
        logging.info("Shutting down server")
    except Exception as e:
        logging.error(f"Server error: {e}")
    finally:
        pump.close()
        server_socket.close()
        logging.info("Resources released and server shut down")

if __name__ == '__main__':
    main()

