import serial
import csv
import os
import time
from datetime import datetime

def celsius_to_fahrenheit(celsius):
    return (celsius * 9/5) + 32

def main():
    port = '/dev/ttyACM0'
    baudrate = 115200
    timeout = 1  # 1 second timeout for readline

    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as e:
        print(f"Error: Could not open port {port}. {e}")
        return 1

    csv_file = 'temperature_log.csv'
    file_exists = os.path.isfile(csv_file)

    try:
        with open(csv_file, mode='a', newline='') as file:
            writer = csv.writer(file)
            if not file_exists:
                writer.writerow(['Timestamp', 'Celsius', 'Fahrenheit'])

            while True:
                try:
                    line = ser.readline().decode('utf-8').strip()
                    if line:
                        try:
                            celsius = float(line)
                            fahrenheit = celsius_to_fahrenheit(celsius)
                            timestamp = datetime.now().strftime('%Y-%m-%d %H:%M:%S')
                            writer.writerow([timestamp, celsius, fahrenheit])
                        except ValueError:
                            print(f"Warning: Malformed or non-numeric line: {line}", file=sys.stderr)
                except KeyboardInterrupt:
                    print("KeyboardInterrupt received. Exiting...")
                    break
                except Exception as e:
                    print(f"Warning: An error occurred: {e}", file=sys.stderr)

    finally:
        ser.close()

if __name__ == "__main__":
    import sys
    sys.exit(main())

