import time
import RPi.GPIO as GPIO

# Constants
DHT_PIN = 4
MAX_RETRIES = 3
RETRY_DELAY = 2
SUCCESS_DELAY = 5
START_SIGNAL_DURATION = 0.018  # 18 ms
RESPONSE_TIMEOUT = 0.00008  # 80 µs
BIT_DURATION = 0.00005  # 50 µs

def setup_gpio():
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(DHT_PIN, GPIO.OUT)
    GPIO.output(DHT_PIN, GPIO.HIGH)

def cleanup_gpio():
    GPIO.cleanup()

def start_signal():
    GPIO.output(DHT_PIN, GPIO.LOW)
    time.sleep(START_SIGNAL_DURATION)
    GPIO.output(DHT_PIN, GPIO.HIGH)

def read_response():
    GPIO.setup(DHT_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    start_time = time.time()
    while GPIO.input(DHT_PIN) == GPIO.LOW:
        if time.time() - start_time > RESPONSE_TIMEOUT:
            return None
    start_time = time.time()
    while GPIO.input(DHT_PIN) == GPIO.HIGH:
        if time.time() - start_time > RESPONSE_TIMEOUT:
            return None
    return time.time() - start_time

def read_bit():
    start_time = time.time()
    while GPIO.input(DHT_PIN) == GPIO.LOW:
        if time.time() - start_time > RESPONSE_TIMEOUT:
            return None
    start_time = time.time()
    while GPIO.input(DHT_PIN) == GPIO.HIGH:
        if time.time() - start_time > RESPONSE_TIMEOUT:
            return None
    return 0 if time.time() - start_time < BIT_DURATION else 1

def read_byte():
    byte = 0
    for _ in range(8):
        bit = read_bit()
        if bit is None:
            return None
        byte = (byte << 1) | bit
    return byte

def read_sensor():
    retries = 0
    while retries < MAX_RETRIES:
        start_signal()
        time.sleep(RESPONSE_TIMEOUT)

        data = []
        for _ in range(5):
            byte = read_byte()
            if byte is None:
                break
            data.append(byte)

        if len(data) == 5 and (data[4] == (data[0] + data[1] + data[2] + data[3]) & 0xFF):
            humidity = data[0] + data[1] / 10.0
            temperature = data[2] + data[3] / 10.0
            return temperature, humidity

        retries += 1
        time.sleep(RETRY_DELAY)

    return None, None

def main():
    try:
        setup_gpio()
        while True:
            temperature, humidity = read_sensor()
            if temperature is not None and humidity is not None:
                print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                time.sleep(SUCCESS_DELAY)
            else:
                print("Error: Failed to read sensor data after 3 attempts.")
                time.sleep(5)
    except KeyboardInterrupt:
        pass
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        cleanup_gpio()

if __name__ == "__main__":
    main()

