# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TEMP_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0
READ_DELAY = 1  # seconds

def read_sensor_data(serial_port):
    try:
        with serial.Serial(serial_port, BAUD_RATE, timeout=2) as ser:
            while True:
                try:
                    line = ser.readline().decode('utf-8').strip()
                    if not line:
                        logging.warning("Empty line received.")
                        continue

                    try:
                        temperature, humidity = map(float, line.split(','))
                    except ValueError:
                        logging.error(f"Malformed line: {line}")
                        continue

                    print(f"{temperature},{humidity}")

                    if temperature > TEMP_THRESHOLD:
                        logging.warning(f"Temperature alert: {temperature}°C")
                    if humidity > HUMIDITY_THRESHOLD:
                        logging.warning(f"Humidity alert: {humidity}%")

                except serial.SerialException as e:
                    logging.error(f"Serial error: {e}")
                except Exception as e:
                    logging.error(f"Unexpected error: {e}")

                time.sleep(READ_DELAY)

    except serial.SerialException as e:
        logging.error(f"Failed to open serial port {serial_port}: {e}")
    except KeyboardInterrupt:
        logging.info("Program interrupted by user.")
    finally:
        logging.info("Exiting program.")

if __name__ == "__main__":
    read_sensor_data(SERIAL_PORT)

