import smbus
import time
from datetime import datetime

# Constants for the BME280 sensor
BME280_ADDRESS = 0x76
BME280_HUMIDITY_REG = 0xFD
BME280_HUMIDITY_CALIB = [0xE1, 0xE3, 0xE5, 0xE7, 0xE9, 0xEB, 0xED, 0xEF]

# Initialize I2C bus
bus = smbus.SMBus(1)

def read_bme280_humidity():
    try:
        # Read raw humidity data
        raw_humidity = bus.read_word_data(BME280_ADDRESS, BME280_HUMIDITY_REG)
        # Convert to a 16-bit value
        raw_humidity = (raw_humidity >> 4) & 0xFFFF
        return raw_humidity
    except OSError as e:
        print(f"Error reading BME280 humidity: {e}")
        return None

def classify_humidity(humidity):
    if humidity < 30:
        return "too_dry"
    elif 30 <= humidity < 40:
        return "dry"
    elif 40 <= humidity <= 60:
        return "comfortable"
    else:
        return "too_humid"

def main():
    try:
        for _ in range(5):
            raw_humidity = read_bme280_humidity()
            if raw_humidity is not None:
                humidity = raw_humidity / 1024.0  # Convert to percentage
                band = classify_humidity(humidity)
                timestamp = datetime.now().isoformat()
                print(f"{timestamp} - Humidity: {humidity:.2f}% - Band: {band}")
            time.sleep(2)
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        bus.close()

if __name__ == "__main__":
    main()

