from matplotlib.animation import FuncAnimation
import time

def read_thermal_frame(serial_port):
    try:
        with serial.Serial(serial_port, baudrate=9600, timeout=1) as ser:
            while True:
                line = ser.readline().decode('utf-8').strip()
                if not line:
                    continue
                try:
                    values = list(map(int, line.split(',')))
                    if len(values) == 768:
                        return np.array(values).reshape((24, 32))
                except ValueError:
                    continue
    except serial.SerialException as e:
        print(f"Error opening or reading from serial port: {e}")
        return None

def update_heatmap(frame, heatmap, ax):
    heatmap.set_array(frame)
    ax.figure.canvas.draw()

def main():
    serial_port = '/dev/ttyUSB0'
    last_good_frame = None

    try:
        fig, ax = plt.subplots()
        heatmap = ax.imshow(np.zeros((24, 32)), cmap='inferno', interpolation='nearest', vmin=0, vmax=255)
        plt.colorbar(heatmap)

        def animate(_):
            nonlocal last_good_frame
            frame = read_thermal_frame(serial_port)
            if frame is not None:
                last_good_frame = frame
                update_heatmap(frame, heatmap, ax)

        ani = FuncAnimation(fig, animate, interval=100)
        plt.show()

    except KeyboardInterrupt:
        print("Program interrupted by user.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        plt.close(fig)
        print("Resources cleaned up and program terminated.")

if __name__ == "__main__":
    main()

