import smbus2
import signal
import time
from contextlib import contextmanager

# Constants
MCP23017_ADDRESS = 0x20
MCP23017_IODIRA = 0x00
MCP23017_IODIRB = 0x01
MCP23017_GPIOA = 0x12
MCP23017_GPIOB = 0x13
MCP23017_GPPUA = 0x0C
MCP23017_GPPUB = 0x0D
I2C_BUS = 1
LED_PIN = 0
SWITCH_PIN = 7
DEBOUNCE_TIME = 0.02  # 20ms

@contextmanager
def i2c_bus(bus_number):
    try:
        bus = smbus2.SMBus(bus_number)
        yield bus
    except IOError as e:
        print(f"Error opening I2C bus {bus_number}: {e}")
        raise
    finally:
        if 'bus' in locals():
            bus.close()

def mcp23017_write(bus, register, value):
    try:
        bus.write_byte_data(MCP23017_ADDRESS, register, value)
    except IOError as e:
        print(f"Error writing to register 0x{register:02X}: {e}")
        raise

def mcp23017_read(bus, register):
    try:
        return bus.read_byte_data(MCP23017_ADDRESS, register)
    except IOError as e:
        print(f"Error reading from register 0x{register:02X}: {e}")
        raise

def setup_mcp23017(bus):
    mcp23017_write(bus, MCP23017_IODIRA, 0xFF & ~(1 << LED_PIN))  # Set GPA0 as output
    mcp23017_write(bus, MCP23017_IODIRB, 0xFF | (1 << SWITCH_PIN))  # Set GPB7 as input with pull-up
    mcp23017_write(bus, MCP23017_GPPUB, 0xFF | (1 << SWITCH_PIN))  # Enable pull-up on GPB7

def get_switch_state(bus):
    gpio_b = mcp23017_read(bus, MCP23017_GPIOB)
    return (gpio_b & (1 << SWITCH_PIN)) != 0

def set_led_state(bus, state):
    gpio_a = mcp23017_read(bus, MCP23017_GPIOA)
    if state:
        gpio_a &= ~(1 << LED_PIN)
    else:
        gpio_a |= (1 << LED_PIN)
    mcp23017_write(bus, MCP23017_GPIOA, gpio_a)

def main():
    last_switch_state = None
    last_change_time = 0

    def signal_handler(sig, frame):
        print("\nCleaning up...")
        set_led_state(bus, False)
        exit(0)

    signal.signal(signal.SIGINT, signal_handler)

    try:
        with i2c_bus(I2C_BUS) as bus:
            setup_mcp23017(bus)
            print("Program started. Press Ctrl+C to exit.")

            while True:
                current_switch_state = get_switch_state(bus)
                current_time = time.time()

                if current_switch_state != last_switch_state:
                    if current_time - last_change_time >= DEBOUNCE_TIME:
                        set_led_state(bus, current_switch_state)
                        print(f"LED {'ON' if current_switch_state else 'OFF'}")
                        last_change_time = current_time

                last_switch_state = current_switch_state
                time.sleep(0.01)  # Small delay to prevent excessive CPU usage

    except Exception as e:
        print(f"An error occurred: {e}")
        exit(1)

if __name__ == "__main__":
    main()

