            # Calculate the running average of the samples
            average_amplitude = sum(samples) / len(samples)

            # Print maintenance recommendation based on the average amplitude
            if average_amplitude > 7.5:
                print("Maintenance recommended: wear trend is high")
            else:
                print("Component healthy: no action needed")

    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        # Ensure the sensor is cleaned up
        sensor.close()

