from time import sleep

class MotorError(Exception):
    pass

class Motor:
    def __init__(self, driver, pin):
        if not hasattr(driver, 'set_pwm_frequency') or not hasattr(driver, 'set_pwm_duty_cycle'):
            raise MotorError("Invalid driver library.pi instance")

        self.driver = driver
        self.pin = pin

        try:
            GPIO.setmode(GPIO.BCM)
            GPIO.setup(self.pin, GPIO.OUT)
            self.pwm = GPIO.PWM(self.pin, 1000)
            self.pwm.start(0)
        except Exception as e:
            raise MotorError(f"Failed to initialize motor: {e}")

    def set_frequency(self, freq):
        try:
            if self.driver.set_pwm_frequency(self.pin, freq) != 0:
                raise MotorError("Failed to set frequency")
            self.pwm.ChangeFrequency(freq)
        except Exception as e:
            raise MotorError(f"Error setting frequency: {e}")

    def set_duty_cycle(self, duty):
        if not 0 <= duty <= 255:
            raise MotorError("Duty cycle must be between 0 and 255")
        try:
            if self.driver.set_pwm_duty_cycle(self.pin, duty) != 0:
                raise MotorError("Failed to set duty cycle")
            self.pwm.ChangeDutyCycle(duty / 255.0 * 100)
        except Exception as e:
            raise MotorError(f"Error setting duty cycle: {e}")

    def stop(self):
        self.set_duty_cycle(0)

    def close(self):
        self.stop()
        self.pwm.stop()
        GPIO.cleanup(self.pin)

    def __del__(self):
        self.close()

