import time
import logging
from gpiozero import Servo
from gpiozero.pins.rpigpio import RPiGPIOFactory

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(message)s')

class ServoSweeper:
    def __init__(self, pin=18, frequency=50):
        try:
            self.servo = Servo(pin, pin_factory=RPiGPIOFactory(), initial_value=None)
            self.frequency = frequency
            logging.info("Servo initialized on pin %d with frequency %d Hz", pin, frequency)
        except Exception as e:
            logging.error("Failed to initialize servo: %s", e)
            raise

    def move_to(self, angle):
        duty_cycle = self._angle_to_duty_cycle(angle)
        self.servo.value = duty_cycle
        logging.info("Moved servo to angle: %d", angle)

    def stop(self):
        self.servo.value = None
        logging.info("Servo stopped")

    def _angle_to_duty_cycle(self, angle):
        # SG90 servo: 0.5 ms for 0 degrees, 2.5 ms for 180 degrees
        pulse_width = (angle / 180.0) * 2.0 + 0.5
        duty_cycle = pulse_width / 20.0  # 20 ms period
        return duty_cycle

def main():
    try:
        sweeper = ServoSweeper()
        angles = [0, 45, 90, 135, 180, 135, 90, 45, 0]
        for angle in angles:
            sweeper.move_to(angle)
            time.sleep(0.5)
    except Exception as e:
        logging.error("An error occurred: %s", e)
    finally:
        sweeper.stop()

if __name__ == "__main__":
    main()

