        if not self.instrument:
            logger.warning("Modbus instrument not initialized.")
            return None
        try:
            return self.instrument.read_registers(start_address, number_of_registers, functioncode=3)
        except minimalmodbus.NoResponseError:
            logger.warning("No response from Modbus device.")
        except minimalmodbus.InvalidResponseError:
            logger.warning("Invalid response from Modbus device.")
        except Exception as e:
            logger.warning(f"Error reading holding registers: {e}")
        return None

    def write_single_holding_register(self, address, value):
        if not self.instrument:
            logger.warning("Modbus instrument not initialized.")
            return False
        try:
            self.instrument.write_register(address, value, functioncode=6)
            return True
        except Exception as e:
            logger.warning(f"Error writing single holding register: {e}")
        return False

    def write_multiple_holding_registers(self, start_address, values):
        if not self.instrument:
            logger.warning("Modbus instrument not initialized.")
            return False
        try:
            self.instrument.write_registers(start_address, values, functioncode=16)
            return True
        except Exception as e:
            logger.warning(f"Error writing multiple holding registers: {e}")
        return False

    def cleanup(self):
        if self.instrument:
            self.instrument.serial.close()
            logger.info("Modbus instrument resources cleaned up.")

@contextmanager
def modbus_controller(port='/dev/serial0', baudrate=115200):
    controller = ModbusRTUServoController(port, baudrate)
    try:
        yield controller
    finally:
        controller.cleanup()

def signal_handler(sig, frame):
    logger.info("Signal received, cleaning up resources.")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    with modbus_controller() as controller:
