            if registers is not None:
                logger.info(f"Read registers: {registers}")

            # Write single holding register
            success = controller.write_single_holding_register(0x0001, 123)
            if success:
                logger.info("Single holding register written successfully.")

            # Write multiple holding registers
            success = controller.write_multiple_holding_registers(0x0002, [456, 789])
            if success:
                logger.info("Multiple holding registers written successfully.")
        else:
            logger.warning("Modbus controller not available.")

