            self.instrument.serial.bytesize = 8
            self.instrument.serial.parity = serial.PARITY_NONE
            self.instrument.serial.stopbits = 1
            self.instrument.serial.timeout = 1
            logging.info("Serial port opened successfully.")
        except Exception as e:
            logging.error(f"Failed to open serial port: {e}")
            sys.exit(0)

    def move_motor(self, position):
        if not isinstance(position, int):
            logging.error("Invalid position type. Must be an integer.")
            return -1
        try:
            self.instrument.write_register(0x00, position)
            logging.info(f"Motor moved to position {position}.")
            return 0
        except minimalmodbus.NoResponseError:
            logging.error("No response from the motor.")
            return -2
        except minimalmodbus.SlaveReportedError as e:
            logging.error(f"Slave reported error: {e}")
            return -3
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            return -4

    def read_feedback(self):
        try:
            position = self.instrument.read_register(0x01)
            logging.info(f"Motor feedback position: {position}.")
            return position
        except minimalmodbus.NoResponseError:
            logging.error("No response from the motor.")
            return -2
        except minimalmodbus.SlaveReportedError as e:
            logging.error(f"Slave reported error: {e}")
            return -3
        except Exception as e:
            logging.error(f"Unexpected error: {e}")
            return -4

    def cleanup(self):
        if self.instrument:
            self.instrument.serial.close()
            logging.info("Serial port closed.")

def signal_handler(sig, frame):
    logging.info("Signal received, cleaning up and exiting.")
    controller.cleanup()
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    controller = ModbusServoController()

    try:
        if controller.move_motor(100) == 0:
            feedback = controller.read_feedback()
            if feedback != -2 and feedback != -3 and feedback != -4:
                logging.info(f"Feedback received: {feedback}")
    except Exception as e:
        logging.error(f"An error occurred during operation: {e}")
    finally:
        controller.cleanup()
