from gpiozero import DigitalOutputDevice, PWMOutputDevice
import time
import signal
import sys

class Laser:
    def __init__(self, pin):
        try:
            self.laser = DigitalOutputDevice(pin)
        except Exception as e:
            print(f"Error initializing laser on GPIO {pin}: {e}")
            sys.exit(1)

    def on(self):
        self.laser.on()

    def off(self):
        self.laser.off()

    def close(self):
        self.laser.close()

class Aim:
    def __init__(self, hp, vp, ld, sd):
        self.hp = hp
        self.vp = vp
        self.ld = ld
        self.sd = sd
        try:
            self.horizontal_servo = PWMOutputDevice(18)
            self.vertical_servo = PWMOutputDevice(19)
        except Exception as e:
            print(f"Error initializing servos: {e}")
            sys.exit(1)

    def move_servo(self, servo, index):
        if 0 <= index < len(servo):
            pulse_width = servo[index]
            servo.value = pulse_width
        else:
            print(f"Invalid index {index} for servo.")

    def aim(self, targets):
        try:
            for target in targets:
                b = target - 1
                self.move_servo(self.horizontal_servo, b)
                self.move_servo(self.vertical_servo, b)
                self.laser.on()
                time.sleep(self.ld)
                self.laser.off()
                time.sleep(self.sd / 2)

            # Move to neutral position
            self.move_servo(self.horizontal_servo, 10)
            time.sleep(self.sd / 2)
            self.move_servo(self.vertical_servo, 10)
        except Exception as e:
            print(f"Error during aiming sequence: {e}")

    def close(self):
        self.horizontal_servo.close()
        self.vertical_servo.close()

def cleanup(signum, frame):
    print("Cleaning up...")
