import smbus2
import time

class I2CDevice:
    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus_number = bus_number
        self.bus = None
        try:
            self.bus = smbus2.SMBus(self.bus_number)
            self._probe_device()
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to initialize I2C device at address {self.address}: {e}")

    def _probe_device(self):
        try:
            # Attempt to read a byte from the device to confirm it's present
            self.bus.read_byte(self.address)
        except (OSError, IOError):
            raise RuntimeError(f"Device at address {self.address} did not acknowledge")

    def write_byte(self, register, value):
        try:
            self.bus.write_byte_data(self.address, register, value)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to write to register {register}: {e}")

    def read_byte(self, register):
        try:
            return self.bus.read_byte_data(self.address, register)
        except (OSError, IOError) as e:
            raise RuntimeError(f"Failed to read from register {register}: {e}")

    def close(self):
        if self.bus:
            self.bus.close()
            self.bus = None

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

