import smbus2
import signal
import sys
from datetime import datetime, timedelta

# Constants
DS1338_ADDRESS = 0x68
I2C_BUS = 1
SDA_PIN = 2
SCL_PIN = 3

# Register addresses
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07

# BCD to integer conversion
def bcd_to_int(bcd):
    return (bcd // 16) * 10 + (bcd % 16)

# Integer to BCD conversion
def int_to_bcd(value):
    return (value // 10) * 16 + (value % 10)

class DS1338:
    def __init__(self):
        self.bus = smbus2.SMBus(I2C_BUS)
        self.verify_rtc()

    def verify_rtc(self):
        try:
            self.bus.read_byte_data(DS1338_ADDRESS, REG_SECONDS)
        except OSError:
            print("DS1338 RTC not found on I2C bus.")
            sys.exit(1)

    def read_register(self, reg):
        try:
            return self.bus.read_byte_data(DS1338_ADDRESS, reg)
        except OSError as e:
            print(f"Error reading register {reg}: {e}")
            return None

    def write_register(self, reg, value):
        try:
            self.bus.write_byte_data(DS1338_ADDRESS, reg, value)
        except OSError as e:
            print(f"Error writing register {reg}: {e}")

    def read_datetime(self, century=21):
        seconds = self.read_register(REG_SECONDS)
        minutes = self.read_register(REG_MINUTES)
        hours = self.read_register(REG_HOURS) & 0x3F  # Mask bit 6
        day = self.read_register(REG_DAY)
        date = self.read_register(REG_DATE)
        month = self.read_register(REG_MONTH)
        year = self.read_register(REG_YEAR)

        if seconds is None or minutes is None or hours is None or day is None or date is None or month is None or year is None:
            return None

        year += century * 100
        return datetime(year, bcd_to_int(month), bcd_to_int(date), bcd_to_int(hours), bcd_to_int(minutes), bcd_to_int(seconds))

    def write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        if seconds is not None:
            self.write_register(REG_SECONDS, int_to_bcd(seconds))
        if minutes is not None:
            self.write_register(REG_MINUTES, int_to_bcd(minutes))
        if hours is not None:
            self.write_register(REG_HOURS, int_to_bcd(hours) & 0x3F)  # Clear bit 6
        if day is not None:
            self.write_register(REG_DAY, day)
        if date is not None:
            self.write_register(REG_DATE, int_to_bcd(date))
        if month is not None:
            self.write_register(REG_MONTH, int_to_bcd(month))
        if year is not None:
            self.write_register(REG_YEAR, int_to_bcd(year % 100))  # Only store the last two digits

    def close(self):
        self.bus.close()

def signal_handler(sig, frame):
    print("Exiting...")
    rtc.close()
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    rtc = DS1338()

    # Example usage
    current_time = rtc.read_datetime()
    if current_time:
        print(f"Current time: {current_time}")

    # Set a new time
