        return (bcd // 16) * 10 + (bcd % 16)

    def _dec_to_bcd(self, dec):
        return (dec // 10) * 16 + (dec % 10)

    def _read_register(self, reg):
        try:
            return self.bus.read_byte_data(self.DEVICE_ADDRESS, reg)
        except Exception as e:
            raise IOError(f"Failed to read register {reg:02x}: {e}")

    def _write_register(self, reg, value):
        try:
            self.bus.write_byte_data(self.DEVICE_ADDRESS, reg, value)
        except Exception as e:
            raise IOError(f"Failed to write register {reg:02x}: {e}")

    def read_all(self):
        seconds = self._read_register(self.REG_SECONDS) & 0x7F
        minutes = self._read_register(self.REG_MINUTES)
        hours = self._read_register(self.REG_HOURS) & 0x3F
        date = self._read_register(self.REG_DATE)
        month = self._read_register(self.REG_MONTH)
        day = self._read_register(self.REG_DAY)
        year = self._bcd_to_dec(self._read_register(self.REG_YEAR)) + 2000

        return (year, month, date, day, hours, minutes, seconds)

    def read_datetime(self):
        year, month, date, day, hours, minutes, seconds = self.read_all()
        return datetime(year, month, date, hours, minutes, seconds, tzinfo=timezone.utc)

