                except serial.SerialException as e:
                    print(f"Serial error: {e}")
                except IOError as e:
                    print(f"IO error: {e}")
                time.sleep(5)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
        sys.exit(1)

if __name__ == "__main__":
    read_co2_sensor()

