import serial
import time
import signal
import sys

class ESP8266Controller:
    def __init__(self, port='/dev/serial0', baud_rate=115200, timeout=1.0):
        self.port = port
        self.baud_rate = baud_rate
        self.timeout = timeout
        self.uart = None
        try:
            self.uart = serial.Serial(port, baud_rate, timeout=timeout)
        except serial.SerialException as e:
            print(f"Failed to open UART port {port}: {e}")
            sys.exit(1)

    def _send_command(self, command, terminator=b'OK', timeout=None):
        if timeout is None:
            timeout = self.timeout
        try:
            self.uart.write(command.encode() + b'\r\n')
            start_time = time.time()
            response = bytearray()
            while time.time() - start_time < timeout:
                if self.uart.in_waiting:
                    response.extend(self.uart.read(self.uart.in_waiting))
                    if any(response.endswith(t) for t in (b'OK', b'ERROR', b'FAIL')):
                        return response
            return None
        except Exception as e:
            print(f"Error sending command: {e}")
            return None

    def test_connection(self):
        response = self._send_command('AT')
        return response is not None and b'OK' in response

    def restart(self):
        self._send_command('AT+RST')
        time.sleep(2)
        return self.test_connection()

    def connect_wifi(self, ssid, password, timeout=10.0):
        response = self._send_command(f'AT+CWJAP="{ssid}","{password}"', timeout=timeout)
        return response is not None and b'OK' in response

    def disconnect_wifi(self):
        response = self._send_command('AT+CWQAP')
        return response is not None and b'OK' in response

    def get_ip(self):
        response = self._send_command('AT+CIFSR')
        if response:
            for line in response.split(b'\r\n'):
                if line.startswith(b'+CIFSR:STAIP,"'):
                    return line.split(b'"')[1].decode()
        return None

    def send_http_request(self, method, url, host, port=80, headers=None, data=None):
        if headers is None:
            headers = {}
        if data is None:
            data = ''
        headers_str = ''.join(f'{k}: {v}\r\n' for k, v in headers.items())
        request = f'{method} {url} HTTP/1.1\r\nHost: {host}\r\nConnection: close\r\n{headers_str}\r\n{data}'
        self._send_command('AT+CIPSTART="TCP","{}",{}'.format(host, port))
        self._send_command('AT+CIPSEND={}'.format(len(request)))
        time.sleep(0.5)  # Give some time for the module to be ready
        self.uart.write(request.encode())
        return self.receive_http_response()

    def receive_http_response(self, timeout=5.0):
        start_time = time.time()
        response = bytearray()
        while time.time() - start_time < timeout:
            if self.uart.in_waiting:
                response.extend(self.uart.read(self.uart.in_waiting))
                if b'CLOSED' in response:
                    return None
                if b'+IPD,' in response:
                    parts = response.split(b'+IPD,', 1)
                    if len(parts) > 1:
                        length = int(parts[1].split(b':')[0])
                        data_start = parts[1].find(b':') + 1
                        payload = parts[1][data_start:data_start + length]
                        return payload
            time.sleep(0.1)
        return None

def signal_handler(sig, frame):
    print('Terminating and closing UART port...')
    if controller.uart:
        controller.uart.close()
    sys.exit(0)

if __name__ == '__main__':
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    controller = ESP8266Controller()
    if controller.test_connection():
        print("ESP8266 is connected.")
    else:
        print("Failed to connect to ESP8266.")

