import serial
import time
import re
import sys

def parse_nmea_gprmc(data):
    try:
        # Split the NMEA sentence into its components
        parts = data.split(',')
        if parts[0] == '$GPRMC' and parts[2] == 'A':
            # Extract latitude and longitude
            lat = parts[3]
            lon = parts[5]
            # Convert latitude
            lat_dir = parts[4]
            lat_deg = float(lat[:2])
            lat_min = float(lat[2:])
            latitude = lat_deg + (lat_min / 60)
            if lat_dir == 'S':
                latitude = -latitude

            # Convert longitude
            lon_dir = parts[6]
            lon_deg = float(lon[:3])
            lon_min = float(lon[3:])
            longitude = lon_deg + (lon_min / 60)
            if lon_dir == 'W':
                longitude = -longitude

            return latitude, longitude
    except Exception as e:
        print(f"Error parsing NMEA data: {e}")
    return None, None

def main():
    ser = None
    try:
        ser = serial.Serial('/dev/serial0', baudrate=9600, timeout=1)
        while True:
            try:
                data = ser.readline().decode('ascii', errors='replace').strip()
                if data:
                    latitude, longitude = parse_nmea_gprmc(data)
                    if latitude is not None and longitude is not None:
                        print(f"Latitude: {latitude:.6f}, Longitude: {longitude:.6f}")
            except serial.SerialException as e:
                print(f"Serial read error: {e}")
            except Exception as e:
                print(f"Unexpected error: {e}")
            time.sleep(1)
    except serial.SerialException as e:
        print(f"Failed to open serial port: {e}")
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        if ser and ser.is_open:
            ser.close()
            print("Serial port closed.")

if __name__ == "__main__":
