            logging.error(f"Failed to open GPS port {self.port}: {e}")
            self.serial_connection = None

    def disconnect(self):
        if self.serial_connection and self.serial_connection.is_open:
            self.serial_connection.close()
            logging.info("Disconnected from GPS module.")
        self.serial_connection = None

    def parse_gpgga(self, sentence):
        try:
            parts = sentence.split(',')
            if len(parts) != 15 or not parts[0].startswith('$GPGGA'):
                raise ValueError("Invalid GPGGA sentence format.")

            talker_id, time, latitude, lat_dir, longitude, lon_dir, fix_quality, satellites, altitude, alt_unit, _, _, _, checksum = parts

            if fix_quality == '0':
                raise ValueError("Invalid fix quality.")

            latitude = self.convert_to_decimal(latitude, lat_dir)
            longitude = self.convert_to_decimal(longitude, lon_dir)
            altitude = float(altitude)
            satellite_count = int(satellites)

            return GPSReadings(latitude, longitude, altitude, satellite_count)
        except (ValueError, IndexError) as e:
            logging.error(f"Error parsing GPGGA sentence: {e}")
            return None

