import sys

class ESP8266UART:
    def __init__(self, port='/dev/serial0', baudrate=115200, timeout=5):
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.serial = None
        self._initialize_uart()

    def _initialize_uart(self):
        try:
            self.serial = serial.Serial(self.port, self.baudrate, timeout=self.timeout, write_timeout=self.timeout)
            self.serial.set_buffer_size(rx_size=4096, tx_size=4096)
        except (serial.SerialException, OSError) as e:
            print(f"Failed to initialize UART: {e}")
            sys.exit(1)

    def _send_command(self, command, delay=1, max_retries=3):
        for attempt in range(max_retries):
            try:
                self.serial.write(f"{command}\r\n".encode('utf-8'))
                time.sleep(delay)
                response = self._read_response()
                if response in ["OK", "ERROR", "FAIL"]:
                    return response
            except serial.SerialException as e:
                print(f"Serial exception during command send: {e}")
            except Exception as e:
                print(f"Unexpected exception during command send: {e}")
        return None

    def _read_response(self):
        start_time = time.time()
        response = b''
        while time.time() - start_time < self.timeout:
            if self.serial.in_waiting:
                response += self.serial.read(self.serial.in_waiting)
                if b"OK" in response or b"ERROR" in response or b"FAIL" in response:
                    return response.decode('utf-8')
        return None

    def test_connection(self):
        return self._send_command("AT") == "OK"

    def restart(self):
        if self._send_command("AT+RST") == "OK":
            time.sleep(2)
            return self.test_connection()
        return False

    def connect_wifi(self, ssid, password):
        command = f'AT+CWJAP_CUR="{ssid}","{password}"'
        if self._send_command(command, delay=5) == "WIFI GOT IP":
            return True
        return False

    def cleanup(self):
        if self.serial and self.serial.is_open:
            self.serial.close()

def signal_handler(sig, frame):
    print("Terminating program and releasing resources...")
    esp8266.cleanup()
    sys.exit(0)

if __name__ == "__main__":
    esp8266 = ESP8266UART()
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

