import serial
import time
import signal
import sys

class GPSModule:
    def __init__(self, port='/dev/ttyAMA0', baud=9600):
        try:
            self.ser = serial.Serial(port, baud, timeout=1)
        except serial.SerialException as e:
            raise RuntimeError(f"Failed to open port {port}: {e}")

    def attach(self):
        try:
            self.ser.write(b"AT+CGNSPWR=1\r\n")
            time.sleep(1)
            if self.ser.in_waiting == 0:
                raise RuntimeError("Failed to power on GNSS")
        except serial.SerialException as e:
            raise RuntimeError(f"Error while attaching GNSS: {e}")

    def detach(self):
        try:
            self.ser.write(b"AT+CGNSPWR=0\r\n")
            time.sleep(1)
            if self.ser.in_waiting == 0:
                raise RuntimeError("Failed to power off GNSS")
        except serial.SerialException as e:
            raise RuntimeError(f"Error while detaching GNSS: {e}")

    def get_data(self):
        try:
            data = self.ser.readline().decode('ascii', errors='ignore').strip()
            if data.startswith('$GPRMC'):
                parts = data.split(',')
                if len(parts) > 2 and parts[2] == 'A':
                    return parts
            return None
        except serial.SerialException as e:
            raise RuntimeError(f"Error while reading data: {e}")

    def close(self):
        if self.ser.is_open:
            self.ser.close()

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        self.close()

def signal_handler(sig, frame):
    print("Exiting...")
    sys.exit(0)

if __name__ == "__main__":
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

