        try:
            self.serial_connection = serial.Serial(self.port, self.baudrate, timeout=1)
            logging.info("Successfully connected to GPS module.")
            return True
        except OSError as e:
            logging.error(f"Failed to connect to GPS module: {e}")
            return False

    def read_data(self):
        if not self.serial_connection or not self.serial_connection.is_open:
            logging.error("GPS connection is not open.")
            return None
        try:
            data = self.serial_connection.readline()
            if data:
                return data.decode('utf-8', errors='ignore').strip()
            return None
        except Exception as e:
            logging.error(f"Error reading data from GPS: {e}")
            return None

    def parse_gga(self, line):
        if not line.startswith(("$GPGGA", "$GNGGA")):
            return None
        try:
            parts = line.split(',')
            if len(parts) < 15:
                return None
            utc_time = parts[1]
            latitude = self._convert_to_decimal_degrees(parts[2], parts[3])
            longitude = self._convert_to_decimal_degrees(parts[4], parts[5])
            fix_quality = int(parts[6]) if parts[6] else None
            num_satellites = int(parts[7]) if parts[7] else None

            return {
                'utc_time': utc_time,
                'latitude': latitude,
                'longitude': longitude,
                'fix_quality': fix_quality,
                'num_satellites': num_satellites
            }
        except (IndexError, ValueError) as e:
            logging.error(f"Error parsing GGA sentence: {e}")
            return None

    def _convert_to_decimal_degrees(self, value, direction):
        if not value:
            return None
        try:
            degrees = float(value[:2])
            minutes = float(value[2:])
            decimal_degrees = degrees + minutes / 60
            if direction in ['S', 'W']:
                decimal_degrees = -decimal_degrees
            return decimal_degrees
        except ValueError:
            return None

    def close(self):
        if self.serial_connection and self.serial_connection.is_open:
            try:
                self.serial_connection.close()
                logging.info("GPS connection closed.")
            except Exception as e:
                logging.error(f"Error closing GPS connection: {e}")
            finally:
                self.serial_connection = None

if __name__ == "__main__":
    gps = SimpleGPS()
    if not gps.connect():
        exit(1)

