import time

app = Flask(__name__)
uart_lock = threading.Lock()
uart_port = None
data_lock = threading.Lock()
data_store = [{'id': 1, 'name': 'Item 1', 'done': False}, {'id': 2, 'name': 'Item 2', 'done': True}]
next_id = 3

def open_uart():
    global uart_port
    with uart_lock:
        if uart_port is None:
            try:
                uart_port = Serial('/dev/ttyUSB0', baudrate=9600, timeout=1)
            except SerialException:
                return False
    return True

def close_uart():
    global uart_port
    with uart_lock:
        if uart_port is not None:
            uart_port.close()
            uart_port = None

def send_scpi_command(command):
    if not open_uart():
        return None
    try:
        with uart_lock:
            uart_port.write(command.encode('ascii'))
            uart_port.flush()
            response = uart_port.readline().decode('ascii').strip()
        return response
    except (SerialException, Timeout):
        return None
    finally:
        close_uart()

@app.route('/version', methods=['GET'])
def get_version():
    response = send_scpi_command('*IDN?\n')
    if response is None:
        return 'Instrument not responding', 500
    return response, 200

@app.route('/data', methods=['GET'])
def get_data():
    with data_lock:
        return jsonify(data_store), 200

@app.route('/data/<int:item_id>', methods=['GET'])
def get_data_item(item_id):
    with data_lock:
        item = next((item for item in data_store if item['id'] == item_id), None)
    if item is None:
        abort(404)
    return jsonify(item), 200

@app.route('/data', methods=['POST'])
def create_data_item():
    global next_id
    content = request.json
    if not content or 'name' not in content or 'done' not in content:
        abort(400)
    if not isinstance(content['name'], str) or not isinstance(content['done'], bool):
        abort(400)
    with data_lock:
        new_item = {'id': next_id, 'name': content['name'], 'done': content['done']}
        data_store.append(new_item)
        next_id += 1
    return jsonify(new_item), 201

