def read_pulse_oximeter_data(port='/dev/ttyUSB0', baudrate=9600, timeout=1):
    try:
        with serial.Serial(port, baudrate, timeout=timeout, bytesize=serial.EIGHTBITS, parity=serial.PARITY_NONE, stopbits=serial.STOPBITS_ONE) as ser:
            while True:
                try:
                    line = ser.readline().decode('ascii', errors='replace').strip()
                    if not line:
                        continue
                    fields = line.split(',')
                    if len(fields) != 2:
                        raise ValueError(f"Invalid data format: {line}")
                    heart_rate, spo2 = fields
                    print(f"Heart Rate: {heart_rate} bpm, SpO2: {spo2} %")
                except ValueError as ve:
                    print(f"Warning: {ve}")
                except serial.SerialException as se:
                    print(f"Error reading from serial port: {se}")
                    break
                time.sleep(1)
    except serial.SerialException as se:
        print(f"Error opening serial port: {se}")
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        if 'ser' in locals() and ser.is_open:
            ser.close()

if __name__ == "__main__":
    read_pulse_oximeter_data()

