app = Flask(__name__)

# Initialize the in-memory list
data_list = [
    {"id": 1, "name": "Item 1", "done": False},
    {"id": 2, "name": "Item 2", "done": False}
]

# Serial connection setup
try:
    ser = serial.Serial('/dev/ttyUSB0', 9600, timeout=1)
except serial.SerialException as e:
    print(f"Error opening serial port: {e}")
    ser = None

def query_instrument(command):
    if ser is None:
        return None
    try:
        ser.write(command.encode('utf-8'))
        time.sleep(0.1)
        response = ser.read_all().decode('utf-8')
        return response
    except serial.SerialException as e:
        print(f"Error communicating with instrument: {e}")
        return None

@app.route('/version', methods=['GET'])
def version():
    response = query_instrument("*IDN?\n")
    if response is None:
        abort(503, description="Failed to communicate with the instrument")
    html_response = response.replace('\n', '<br>')
    return f"<html><body><pre>{html_response}</pre></body></html>", 200

@app.route('/getdata', methods=['GET'])
def get_data():
    return jsonify(data_list), 200

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_set_item(item_id):
    item = next((item for item in data_list if item['id'] == item_id), None)
    if item is None:
        abort(404, description="Item not found")
    return jsonify(item), 200

@app.route('/getpost/<int:item_id>/<name>', methods=['GET', 'POST'])
