    return jsonify(error=str(e)), 400

def cleanup():
    if ser is not None:
        ser.close()

if __name__ == '__main__':
    try:
        app.run(host='0.0.0.0', port=5000)
    except Exception as e:
        print(f"Error running the Flask app: {e}")
    finally:
        cleanup()

